Implement type-safety improvements:

1. Create domain mapper layer in shared/src/mappers/:
```typescript
// shared/src/mappers/document-mappers.ts
import type { IssueDocument, ProjectDocument, ... } from '../types/document';
import type { IssueProperties, ProjectProperties, ... } from '../types/properties';

export function mapIssueDocument(row: any): IssueDocument {
  return {
    ...row,
    content: row.content as JSONContent,
    properties: row.properties as IssueProperties,
  };
}
// Repeat for all document types
```
